// 2 이상 N 이하의 소수를 모두 표시한다 (에라토스테네스의 체)
vector<bool> composite(N + 1, false);
for (int i = 2; i * i <= N; i++)
    if (!composite[i])
        for (int j = i * i; j <= N; j += i)
            composite[j] = true;        // i의 배수를 지운다
// composite[x]가 false인 2 이상의 x가 소수

